package org.apache.commons.cli;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;

public class OptionBuilderWithDescriptionTest {

    private Field descriptionField;
    private Field instanceField;

    @BeforeEach
    public void setUp() throws Exception {
        descriptionField = OptionBuilder.class.getDeclaredField("description");
        descriptionField.setAccessible(true);
        // ensure a clean start: null description
        descriptionField.set(null, null);

        instanceField = OptionBuilder.class.getDeclaredField("INSTANCE");
        instanceField.setAccessible(true);
    }

    @AfterEach
    public void tearDown() throws Exception {
        // reset description to null after each test to avoid cross-test pollution
        if (descriptionField != null) {
            descriptionField.set(null, null);
        }
    }

    @Test
    public void testWithDescriptionSetsDescriptionAndReturnsSingletonInstance() throws Exception {
        String desc = "my description";
        OptionBuilder returned = OptionBuilder.withDescription(desc);

        // verify returned instance is the private INSTANCE
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withDescription should return the singleton INSTANCE");

        // verify the private description field is updated
        Object stored = descriptionField.get(null);
        assertEquals(desc, stored, "description field should be set to the provided string");
    }

    @Test
    public void testWithDescriptionWithNullSetsDescriptionToNullAndReturnsSingleton() throws Exception {
        // start with a non-null description to ensure null overwrites
        descriptionField.set(null, "initial");
        OptionBuilder returned = OptionBuilder.withDescription(null);

        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withDescription(null) should still return the singleton INSTANCE");

        Object stored = descriptionField.get(null);
        assertNull(stored, "description field should be set to null when called with null");
    }

    @Test
    public void testMultipleCallsReturnSameInstanceAndLatestDescriptionWins() throws Exception {
        OptionBuilder first = OptionBuilder.withDescription("first");
        OptionBuilder second = OptionBuilder.withDescription("second");

        // both calls should return same singleton instance
        assertSame(first, second, "multiple calls should return the same singleton instance");
        Object instance = instanceField.get(null);
        assertSame(instance, first, "returned instance should be the private INSTANCE");

        // description should reflect the latest call
        Object stored = descriptionField.get(null);
        assertEquals("second", stored, "description should reflect the latest value passed to withDescription");
    }
}

